    function Y2(e2, t2, n2, r = {}) {
      return Wo2(e2, {
        signature: t2,
        hint: n2,
        template: r.template,
        usage: r.usage ?? (/\(\)/.test(t2) ? ["直接插入即可返回该函数的固定结果。"] : ["按参数顺序填写数字、区域、条件或概率参数即可。"])
      });
    }
